/**
 * Debounces an async API call with cancellation support.
 *
 * @param {AbortController} controller - The AbortController instance to use for cancellation.
 * @param {function} apiCall - The async API call to debounce.
 * @param {number} delay - The debounce delay in milliseconds.
 * @returns {Promise} The result of the debounced API call.
 */
function debounceApiCall(controller, apiCall, delay) {
  let timeoutId;
  let pendingCall;

  return function debouncedApiCall() {
    // Cancel any pending call
    if (pendingCall) {
      pendingCall.cancel();
    }

    // Create a new AbortSignal from the provided AbortController
    const signal = controller.signal;

    // Set the pending call
    pendingCall = {
      cancel: () => {
        // Cancel the pending call
        signal.abort();
      },
    };

    // Wait for the debounce delay
    return new Promise((resolve, reject) => {
      timeoutId = globalThis.setTimeout(() => {
        // Clear the pending call
        pendingCall = null;

        // Call the API with the signal
        apiCall(signal)
          .then((result) => {
            resolve(result);
          })
          .catch((error) => {
            reject(error);
          });
      }, delay);
    });
  };
}

